## **Bug Details**
Using `by llm(..., tools=([...]))` with node methods (e.g., `self.add`) raises an error:

```
ERROR - 'method' object has no attribute '__annotations__'
```
But the same function works correctly if declared in the global scope.

### **To Reproduce**
```py
import from mtllm.llm { Model }

glob llm = Model(model_name="gpt-4o-mini", verbose=False);

node Calculator {
    def add(num1: int, num2: int) -> int {
        print("adding numbers");
        return num1 + num2;
    }

    def select_and_run(expression: str) -> str by llm(
        method="ReAct",
        tools=([self.add])   # ❌ fails here
    );
    can execute with calculation_walker entry {
        print("Answer: ", self.select_and_run(visitor.expression));
    }
}

walker calculation_walker {
    has expression: str = "";
}

with entry {
    calc = Calculator();
    calculation_walker("Can you tell me the answer of 2+3?") spawn calc;
}
```

Error output
```
ERROR - 'method' object has no attribute '__annotations__'
```

### **Workaround (Works as Expected)**

If the function is declared in global scope, it works fine:

```py
import from mtllm.llm { Model }

glob llm = Model(model_name="gpt-4o-mini", verbose=False);

def add(num1: int, num2: int) -> int {
    print("adding numbers");
    return num1 + num2;
}

node Calculator {
    def select_and_run(expression: str) -> str by llm(
        method="ReAct",
        tools=([add])   # ✅ works
    );
    can execute with calculation_walker entry {
        print("Answer: ", self.select_and_run(visitor.expression));
    }
}

walker calculation_walker {
    has expression: str = "";
}

with entry {
    calc = Calculator();
    calculation_walker("Can you tell me the answer of 2+3?") spawn calc;
}
```

### **Expected Behavior**
Node methods (like `self.add`) should be supported as tools in `by llm`, the same way global functions are.

### **Actual Behavior**
- Passing a node method as a tool fails with `__annotations__` error.
- Passing a global function works correctly.

### **Environment**

- OS: Windows WSL
- Python Version: 3.13
- Jac Version: 0.8.5
- mtllm Version: 0.4.0
